const payment = $input.first().json;
const meta = payment.metadata || {};
const payer = payment.payer || {};

const nome = payer.first_name
  ? `${payer.first_name} ${payer.last_name || ''}`.trim()
  : (meta.nome || 'Afiliado');

return [{
  json: {
    order_id: payment.id?.toString() || String(Date.now()),
    nome: nome,
    email: payer.email || meta.email || '',
    telegram_username: meta.telegram_username || '',
    valor: payment.transaction_amount?.toFixed(2) || '12.90',
    status_pagamento: 'aprovado',
    status_pedido: 'novo',
    criado_em: new Date().toISOString(),
    aprovado_em: null,
    log_email: ''
  }
}];

