const payment = $input.first().json;
const statusMap = {
  rejected: 'recusado',
  cancelled: 'recusado',
  refunded: 'estornado',
  charged_back: 'estornado'
};
const payer = payment.payer || {};

return [{
  json: {
    order_id: payment.id?.toString() || '',
    email: payer.email || '',
    status_pagamento: statusMap[payment.status] || payment.status,
    status_pedido: 'rejeitado'
  }
}];
